# Public API (cm:*)
  @api cm:setContext(newTake)  @ 423-428
      @contract  setContext(nil) clears take+track; setContext(take) derives track via GetMediaItemTrack  @ 421
      @contract  refreshes all persisted caches (transient resets to {}) and fires configChanged {}  @ 422
  @api cm:clearTake()  @ 430-435
  @api cm:boundTake()  @ 438
      @contract  bound take pointer; nil when context is cleared (take/track tiers resolve off empty)  @ 437
  @api cm:boundTrack()  @ 441
      @contract  bound track pointer; nil when context is cleared (track tier resolves off empty)  @ 440
  @api cm:setTrack(newTrack)  @ 443-448
  @api cm:pollUndo()  @ 451
      @contract  delegates to the engine watcher; cm's watch group reloads tiers and fires configChanged  @ 450
  @api cm:isDeclared(key)  @ 488
      @contract  non-raising existence test against the schema; true iff key is declared  @ 487
  @api cm:get(key, opts)  @ 495-502
      -- pick is orthogonal to the merge mode: it indexes whatever that mode resolved, so only the
      -- one entry crosses the boundary. A nil pick is indistinguishable from none (see the spec).
  @api cm:getAt(level, key)  @ 505-514
      @contract  reads single tier only (no merge, no defaults); key nil → whole-cache clone  @ 504
  @api cm:valueFor(handle, scope, key)  @ 517-524
      @contract  single-tier value for a foreign take/track handle (ps:getAt); no merge or defaults  @ 516
  @api cm:defaultFor(key)  @ 527-530
      @contract  deep-copy of the schema default for key (no tiers, no merge); raises on unknown key  @ 526
  -- Writing
  @api cm:set(level, key, value)  @ 535-545
      @contract  deep-copies value into tier cache, persists, fires targeted configChanged  @ 534
  @api cm:remove(level, key)  @ 548-559
      @contract  removes key from named tier; no-op (no signal) if that tier's cache is unloaded  @ 547
  @api cm:assign(level, updates)  @ 562-576
      @contract  validates all keys before any write (all-or-nothing); REMOVE deletes; fires signal  @ 561

